import re

class JSRemover(HTMLParser):
    def __init__(self):
        super().__init__()
        self.output = []
        self.in_script = False
        self.in_style = False  # keep style? could contain JS but usually CSS; we'll keep.

    def handle_starttag(self, tag, attrs):
        if tag.lower() == 'script':
            self.in_script = True
            # Do not output the script tag
            return
        if tag.lower() == 'style':
            self.in_style = True
        # Process attributes: remove event handlers and javascript: URLs
        filtered = []
        for name, value in attrs:
            if value is None:
                filtered.append((name, value))
                continue
            # Remove event handlers (onclick, onload, etc.)
            if re.match(r'^on[a-z]+', name, re.I):
                continue
            # Remove href="javascript:..." and similar
            if re.match(r'^javascript:', value, re.I):
                continue
            # Remove data: URLs that could be scripts? Not removing data:.
            filtered.append((name, value))
        # Reconstruct start tag
        attrs_str = ''
        for name, value in filtered:
            if value is None:
                attrs_str += f' {name}'
            else:
                # Escape quotes? value may contain quotes; we keep as original.
                attrs_str += f' {name}="{value}"'
        self.output.append(f'<{tag}{attrs_str}>')

    def handle_endtag(self, tag):
        if tag.lower() == 'script':
            self.in_script = False
            return
        if tag.lower() == 'style':
            self.in_style = False
        self.output.append(f'</{tag}>')

    def handle_data(self, data):
        if self.in_script:
            # Discard script content
            return
        # Could also remove inline event handlers within tags? Already handled.
        self.output.append(data)

    def handle_comment(self, data):
        # Remove comments that may contain script? Keep comments.
        self.output.append(f'<!--{data}-->')

    def handle_decl(self, decl):
        self.output.append(f'<!{decl}>')

    def handle_pi(self, data):
        self.output.append(f'<?{data}>')

    def unknown_decl(self, data):
        self.output.append(f'<![{data}]>')

    def get_output(self):
        return ''.join(self.output)

def filter_html(content):
    parser = JSRemover()
    parser.feed(content)
    return parser.get_output()

def main():
    if len(sys.argv) != 2:
        print(f'Usage: {sys.argv[0]} <html_file>')
        sys.exit(1)
    filename = sys.argv[1]
    if not os.path.exists(filename):
        print(f'File not found: {filename}')
        sys.exit(1)
    with open(filename, 'r', encoding='utf-8') as f:
        html = f.read()
    filtered = filter_html(html)
    # Write back in-place
    with open(filename, 'w', encoding='utf-8') as f:
        f.write(filtered)
    print(f'Filtered {filename}')

if __name__ == '__main__':
    main()
